import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    directory = Path(directory_path).expanduser()
    if not directory.is_dir():
        return {}

    result = {}
    tokenizing_patterns = {
        r'\\(.+?\\)|\\w',
        r'\((.+?)\)|\w',
        r'\(.+?\)|\w',
    }

    for file_name in sorted(glob.glob(os.path.join(str(directory), "*"))):
        path = Path(file_name)
        if not path.is_file():
            continue

        try:
            content = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        try:
            if regex_pattern in tokenizing_patterns:
                # Parenthesized content is one token; every other character is individual.
                matches = [
                    m.group(1) if m.group(1) is not None else m.group(0)
                    for m in re.finditer(r"\((.*?)\)|.", content, flags=re.S)
                ]
            else:
                matches = [m.group(0) for m in re.finditer(regex_pattern, content)]
        except re.error:
            matches = []

        result[path.name] = matches

    return result

