import pytz
import numpy as np
from dateutil.parser import parse
import math
from datetime import datetime, timedelta, timezone

MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])

def task_func(date_str, from_tz, to_tz):
    def _get_tz(tz_value):
        if hasattr(tz_value, "utcoffset"):
            return tz_value
        return pytz.timezone(str(tz_value))

    def _localize_naive(dt, tz):
        try:
            return tz.localize(dt, is_dst=None)
        except Exception:
            try:
                return tz.localize(dt, is_dst=False)
            except Exception:
                return tz.localize(dt, is_dst=True)

    def _coerce_datetime(value):
        if isinstance(value, datetime):
            return value
        return parse(str(value))

    def _convert_datetime(dt):
        source_tz = _get_tz(from_tz)
        target_tz = _get_tz(to_tz)

        if dt.tzinfo is None:
            dt = _localize_naive(dt, source_tz)

        return dt.astimezone(target_tz)

    def _moon_phase(dt_utc):
        # Approximate phase using a synodic month and a reference aligned
        # to the 7-year anchor years provided in MOON_PHASES_YEARS.
        synodic_month = 29.53058867
        base_new_moon = datetime(2000, 1, 6, 18, 14, tzinfo=timezone.utc)

        ref_years = np.asarray(MOON_PHASES_YEARS, dtype=int)
        ref_year = int(ref_years[np.argmin(np.abs(ref_years - dt_utc.year))])

        # Use the selected 7-year anchor to stabilize the approximation.
        approx_anchor = datetime(ref_year, 1, 1, tzinfo=timezone.utc)
        cycles = round(
            (approx_anchor - base_new_moon).total_seconds() / (86400.0 * synodic_month)
        )
        epoch = base_new_moon + timedelta(days=cycles * synodic_month)

        lunar_age = ((dt_utc - epoch).total_seconds() / 86400.0) / synodic_month
        lunar_age %= 1.0

        # Map new moon -> 0 and full moon -> 1.
        illumination = 0.5 * (1.0 - math.cos(2.0 * math.pi * lunar_age))
        return float(max(0.0, min(1.0, illumination)))

    parsed = _coerce_datetime(date_str)
    converted = _convert_datetime(parsed)
    return _moon_phase(converted.astimezone(timezone.utc))

